ap:9px}.metrics article{padding:15px}.metrics strong{font-size:26px}.card{padding:19px}.history li{flex-wrap:wrap;gap:6px 12px}.history time{flex-basis:100%}.tabs button{padding:10px}.hero p{font-size:13px}}
